import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.DQhM5RF8.js";const g=JSON.parse('{"title":"Domain Expansions Guide","description":"","frontmatter":{},"headers":[],"relativePath":"info/domains.md","filePath":"info/domains.md"}'),i={name:"info/domains.md"};function r(s,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="domain-expansions-guide" tabindex="-1">Domain Expansions Guide <a class="header-anchor" href="#domain-expansions-guide" aria-label="Permalink to &quot;Domain Expansions Guide&quot;">​</a></h1><p>Domain Expansion is a special arena battle move inspired by <em>Jujutsu Kaisen</em>. It lets you trap nearby players inside a private arena where you control the battle rules.</p><hr><h2 id="what-does-a-domain-do" tabindex="-1">What Does a Domain Do? <a class="header-anchor" href="#what-does-a-domain-do" aria-label="Permalink to &quot;What Does a Domain Do?&quot;">​</a></h2><p>When you activate your domain:</p><ol><li>A giant black barrier bubble appears in the real world around your spot.</li><li>You and any nearby enemies (within 12 blocks) get teleported into a private arena in the sky.</li><li>Outside players cannot enter or interfere with your fight.</li><li>You get to pick a superpower rule that helps you and hurts your enemies.</li><li>The fight lasts <strong>25 seconds</strong>. When time runs out, everyone teleports safely back to where they were standing in the real world.</li></ol><hr><h2 id="how-to-cast-a-domain" tabindex="-1">How to Cast a Domain <a class="header-anchor" href="#how-to-cast-a-domain" aria-label="Permalink to &quot;How to Cast a Domain&quot;">​</a></h2><ol><li>Hold your <strong>Domain Wand</strong> in your main hand.</li><li><strong>Right-click</strong> the ground.</li><li>You and all enemies within 12 blocks are pulled into the arena.</li><li>A 25-second countdown timer appears on your screen.</li></ol><hr><h2 id="picking-your-superpower-rule" tabindex="-1">Picking Your Superpower Rule <a class="header-anchor" href="#picking-your-superpower-rule" aria-label="Permalink to &quot;Picking Your Superpower Rule&quot;">​</a></h2><p>As soon as you enter the arena, you will see 4 special items in your hotbar. Pick the one you want, hold it, and <strong>crouch (sneak)</strong> to lock it in:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Item</th><th style="text-align:left;">Rule Name</th><th style="text-align:left;">What It Gives You</th><th style="text-align:left;">What It Does to Enemies</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Sword</strong></td><td style="text-align:left;">Sovereign Strength</td><td style="text-align:left;">Super Strength &amp; Extra Defense</td><td style="text-align:left;">Hit enemies with massive melee damage.</td></tr><tr><td style="text-align:left;"><strong>Feather</strong></td><td style="text-align:left;">Super Speed</td><td style="text-align:left;">Speed IV and Jump Boost</td><td style="text-align:left;">Slows down enemies to a crawl so they cannot run.</td></tr><tr><td style="text-align:left;"><strong>Golden Apple</strong></td><td style="text-align:left;">Healing Vitality</td><td style="text-align:left;">Super fast heart regeneration</td><td style="text-align:left;">Makes enemies weak so their hits deal less damage.</td></tr><tr><td style="text-align:left;"><strong>Lightning Rod</strong></td><td style="text-align:left;">Divine Lightning</td><td style="text-align:left;">Immune to lightning strikes</td><td style="text-align:left;">Summons endless lightning bolts from the sky onto enemies!</td></tr></tbody></table><p>Once you crouch to pick your rule, your regular weapons and hotbar items come right back so you can fight.</p><hr><h2 id="how-to-defend-yourself-simple-domain" tabindex="-1">How to Defend Yourself (Simple Domain) <a class="header-anchor" href="#how-to-defend-yourself-simple-domain" aria-label="Permalink to &quot;How to Defend Yourself (Simple Domain)&quot;">​</a></h2><p>If an enemy traps <strong>you</strong> inside their domain, you are not helpless! You can use a counter-move called a <strong>Simple Domain</strong>:</p><ul><li>Hold up a <strong>Shield</strong> and <strong>Crouch (Sneak)</strong>.</li><li>A glowing defensive circle will protect your feet.</li><li>While active, it stops enemy lightning strikes from hitting you and clears negative potion effects!</li></ul><hr><h2 id="what-outside-players-can-do" tabindex="-1">What Outside Players Can Do <a class="header-anchor" href="#what-outside-players-can-do" aria-label="Permalink to &quot;What Outside Players Can Do&quot;">​</a></h2><p>If your teammate gets trapped inside an enemy&#39;s domain:</p><ul><li>You will see a giant black glass sphere where they were standing.</li><li>Outsiders can attack the outside barrier. If you hit the barrier <strong>60 times</strong>, it will shatter and force the domain to collapse early!</li></ul><hr><h2 id="rules-limits-cooldowns" tabindex="-1">Rules, Limits &amp; Cooldowns <a class="header-anchor" href="#rules-limits-cooldowns" aria-label="Permalink to &quot;Rules, Limits &amp; Cooldowns&quot;">​</a></h2><ul><li><strong>Your Items Are Safe</strong>: Your original hotbar items are safely saved and returned to you as soon as you pick your rule or leave the domain.</li><li><strong>45-Second Cooldown</strong>: After your domain ends, your powers need to rest for 45 seconds before you can cast another one.</li><li><strong>Server Limit</strong>: Up to <strong>20 domains</strong> can be active on the server at the same time. If 20 are already active, you have to wait for one to finish.</li></ul>',25)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
